const body = pm.response.json();

pm.test("Filtered payments request returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response contains a payments array", function () {
    pm.expect(body.payments).to.be.an("array");
});

if (Array.isArray(body.payments)) {
    const beginTime = Date.parse(
        pm.variables.get("filterBeginTime")
    );

    const endTime = Date.parse(
        pm.variables.get("filterEndTime")
    );

    pm.test("Every payment belongs to the selected location", function () {
        body.payments.forEach(function (payment) {
            pm.expect(payment.location_id)
                .to.equal(pm.variables.get("locationId"));
        });
    });

    pm.test("Every payment is inside the selected date range", function () {
        body.payments.forEach(function (payment) {
            const paymentTime = Date.parse(payment.created_at);

            pm.expect(paymentTime).to.be.at.least(beginTime);
            pm.expect(paymentTime).to.be.at.most(endTime);
        });
    });

    pm.test("Payments are sorted from newest to oldest", function () {
        for (let index = 1; index < body.payments.length; index++) {
            const previousPaymentTime = Date.parse(
                body.payments[index - 1].created_at
            );

            const currentPaymentTime = Date.parse(
                body.payments[index].created_at
            );

            pm.expect(previousPaymentTime)
                .to.be.at.least(currentPaymentTime);
        }
    });

    pm.test("No more than 10 payments are returned", function () {
        pm.expect(body.payments.length).to.be.at.most(10);
    });
}

